-- Descrições dos livros (2026-11-05). Aprovadas pelo dono depois da página de revisão.
-- Versão depois de 20261105065500_capas_certas_do_catalogo (a última por aplicar antes desta).
--
-- Origem: a sinopse de cada livro na loja da Casa Publicadora Brasileira (a editora), limpa de
-- rótulos promocionais ("REFORMULADO"), de publicidade a aplicações e de linhas de ficha técnica.
-- Ficam as indicações de faixa etária. Só texto em parágrafos (<p>, <strong>).
--
-- Só preenche descrições VAZIAS: o que alguém já escreveu no painel não é tocado.
-- COL-001 e COL-002 já tinham descrição; delas sai só a primeira linha, uma nota interna
-- ("[Colportagem] PC: … Kz · … págs · …") que estava à vista dos clientes.
-- LIV-057 e LIV-072 ficam sem descrição: a editora já não os tem no catálogo.
-- Guarda o valor antigo em private.correcoes_dados (migracao = '20261105074300').

insert into private.correcoes_dados (migracao, tabela, accao, linha)
select '20261105074300', 'stock_books', 'alterada', jsonb_build_object('id', id, 'book_code', book_code, 'description', description)
from public.stock_books
where (book_code in ('LIV-001', 'LIV-002', 'LIV-003', 'LIV-004', 'LIV-005', 'LIV-006', 'LIV-007', 'LIV-008', 'LIV-009', 'LIV-010', 'LIV-011', 'LIV-012', 'LIV-013', 'LIV-014', 'LIV-015', 'LIV-016', 'LIV-017', 'LIV-018', 'LIV-019', 'LIV-020', 'LIV-021', 'LIV-022', 'LIV-023', 'LIV-024', 'LIV-025', 'LIV-026', 'LIV-027', 'LIV-028', 'LIV-029', 'LIV-030', 'LIV-031', 'LIV-032', 'LIV-033', 'LIV-034', 'LIV-035', 'LIV-036', 'LIV-037', 'LIV-038', 'LIV-039', 'LIV-040', 'LIV-041', 'LIV-042', 'LIV-043', 'LIV-044', 'LIV-045', 'LIV-046', 'LIV-047', 'LIV-048', 'LIV-049', 'LIV-050', 'LIV-051', 'LIV-052', 'LIV-053', 'LIV-054', 'LIV-055', 'LIV-056', 'LIV-058', 'LIV-059', 'LIV-060', 'LIV-061', 'LIV-062', 'LIV-063', 'LIV-064', 'LIV-065', 'LIV-066', 'LIV-067', 'LIV-068', 'LIV-069', 'LIV-070', 'LIV-071', 'LIV-073', 'LIV-074', 'LIV-075', 'LIV-076', 'LIV-077', 'LIV-078', 'LIV-079', 'LIV-080', 'LIV-081', 'LIV-082', 'LIV-083', 'LIV-084', 'LIV-085', 'LIV-086', 'LIV-087', 'LIV-088', 'LIV-089', 'LIV-090', 'LIV-091', 'LIV-092', 'LIV-093', 'LIV-094', 'LIV-095', 'LIV-096', 'LIV-097', 'LIV-098', 'LIV-099', 'LIV-100')
       and length(trim(regexp_replace(coalesce(description, ''), '<[^>]*>', '', 'g'))) = 0)
   or (book_code in ('COL-001', 'COL-002') and description like '[Colportagem]%');

-- LIV-001 · 101 Perguntas sobre Ellen White e seus Escritos  [CPB, produto 12308 (101 Perguntas Sobre Ellen White e Seus E]
update public.stock_books set description = $sinopse$<p>- Os eventos de 11 de setembro de 2001 cumpriram uma profecia de Ellen White?</p><p>- Ela disse que a Associação Geral era Babilônia?</p><p>- Ellen White cometeu erros?</p><p>- As pessoas alteraram os livros de Ellen White?</p><p>- Podemos confiar nas compilações?</p><p>- Tudo o que ela escreveu é inspirado?</p><p>- As traduções modernas da Bíblia são perigosas?</p><p>Todos os dias, os responsáveis pelo patrimônio literário de Ellen White recebe perguntas sobre ela, seus escritos, sua vida e suas crenças.</p><p>Neste livro, o pastor William Fagal, diretor associado do Ellen G. White Estate, dá respostas instigantes a 101 das perguntas feitas com maior frequência, muitas delas bastante controversas. De forma didática, ele expõe diversos mitos e apresenta ao leitor a verdade sobre essa autora que inspira gerações.</p>$sinopse$
 where book_code = 'LIV-001' and length(trim(regexp_replace(coalesce(description, ''), '<[^>]*>', '', 'g'))) = 0;

-- LIV-002 · 1844 - Uma Explicação Simples das Principais Profecias de Daniel  [CPB, produto 6392 (1844 - Uma Explicação Simples das Princip]
update public.stock_books set description = $sinopse$<p>Para os cristãos de hoje, teria algum significado o ano de 1844 e os tão questionados eventos ligados a ele? Existe algum modo de compreender o confuso labirinto de animais, datas e reinos descritos em Daniel?</p><p>Neste livro, Clifford Goldstein, editor da revista Liberty(EUA) e autor de O Dia do Dragão, soluciona a aparente confusão.</p>$sinopse$
 where book_code = 'LIV-002' and length(trim(regexp_replace(coalesce(description, ''), '<[^>]*>', '', 'g'))) = 0;

-- LIV-003 · 9 Virtudes da Fé  [CPB, produto 20783 (9 Virtudes da Fé)]
update public.stock_books set description = $sinopse$<p>Um Caminho de Graça e Propósito</p><p>Você conhece algum cristão que sempre irradia bondade, independentemente das circunstâncias?Você deseja ter mais alegria, amor, positividade e contentamento em sua vida, mas não sabe como? Se você quer desenvolver um relacionamento genuíno com Jesus, tão poderoso que seja percebido pelas pessoas ao seu redor, então este livro é para você.</p><p>Os autores Julian e Annette Melgosa examinam nove hábitos que incluem resiliência, serenidade e humildade. Eles argumentam que, quando esses hábitos são cultivados, resultam em uma espiritualidade profundamente frutífera e fortalecida. Este livro contém dezenas de tarefas práticas que facilitam a aplicação desses princípios no dia a dia.</p><p>Como a reflexão sincera ajuda as pessoas a adotarem novos hábitos, cada capítulo é encerrado com perguntas que instigarão sua compreensão dos princípios e o motivarão ao comprometimento e à ação.</p><p>Por fim, embora 9 virtudes da Fé ofereça pesquisa científica e estratégias psicológicas para o crescimento pessoal, os autores também enfatizam conteúdo bíblico ao longo do livro. Essa abordagem complementar mostra como, pela graça de Deus, esses hábitos saudáveis podem se tornar parte de sua personalidade.</p><p>Descubra neste livro fantástico como experimentar a alegria, o amor e o contentamento que vêm de uma vida totalmente entregue a Jesus.</p>$sinopse$
 where book_code = 'LIV-003' and length(trim(regexp_replace(coalesce(description, ''), '<[^>]*>', '', 'g'))) = 0;

-- LIV-004 · 95 Teses sobre Justificação pela Fé  [CPB, produto 5286 (95 Teses Sobre Justificação Pela Fé)]
update public.stock_books set description = $sinopse$<p>A teoria da justificação pela fé é dinâmica. Uma vez que a entenda, você nunca mais será o mesmo. Mas a teoria não é suficiente. O poder real vem quando você a experimenta por você mesmo. Leia e obtenha essa experiência ainda hoje!</p>$sinopse$
 where book_code = 'LIV-004' and length(trim(regexp_replace(coalesce(description, ''), '<[^>]*>', '', 'g'))) = 0;

-- LIV-005 · O Que Você Precisa Saber - Adoração  [CPB, produto 18632 (Adoração - Série Essencial)]
update public.stock_books set description = $sinopse$<p>Deus Se importa com o estilo de culto? Como desenvolver uma liturgia reverente e significativa para a comunidade de fé? Há critérios para avaliar as tendências litúrgicas contemporâneas? Como tudo isso afeta a espiritualidade e a vida diária? Afinal, o que é adoração? Ao longo do tempo, o debate em torno dessas perguntas levou às mais variadas respostas, fazendo desse tema um dos mais controvertidos das últimas décadas.</p><p>Em Adoração, O Que Você Precisa Saber, Daniel Plenc oferece respostas bíblicas, objetivas e aplicáveis a esses e outros questionamentos. Partindo do pressuposto de que adoração e eclesiologia (a doutrina da igreja) estão intimamente relacionadas, o autor analisa o assunto à luz da Bíblia e da história do cristianismo. Também sugere práticas que enriquecem a liturgia congregacional e proporcionam uma experiência viva de comunhão com Deus e compromisso com a missão.</p><p>Este é um livro da Série Essencial, que foi pensada para apresentar uma introdução teológica aos temas mais pulsantes do momento, com um texto tão acessível quanto acadêmico. A série oferece recursos indispensáveis para ajudar você a expandir seus conhecimentos por meio de um material objetivo e prático.</p>$sinopse$
 where book_code = 'LIV-005' and length(trim(regexp_replace(coalesce(description, ''), '<[^>]*>', '', 'g'))) = 0;

-- LIV-006 · Adventismo - Origem e Impacto do Movimento Milerita  [CPB, produto 13174 (Adventismo)]
update public.stock_books set description = $sinopse$<p>Quarta-feira, 23 de outubro de 1844 era para ser o primeiro dia no Céu.</p><p>Em vez disso, os crentes adventistas ainda estava na Terra, absortos, em estado de choque e tristeza - motivo de chacota para um mundo incrédulo.</p><p>Eles acreditavam que, de acordo com as profecias, Jesus voltaria em 22 de outubro. Ele não voltou. "Será que a Bíblia está errada?", questionou Hiram Edson, expressando a pergunta que assombrava o rebanho ferido. "Não há Deus, Céu, cidade dourada ou paraíso? Tudo são fábulas engenhosamente inventadas?"</p><p>Neste livro, George Knight reconta a história do grande desapontamento e investiga a dinâmica vital que tornou o Movimento Milerita um marco histórico para o cristianismo.</p><p>Após 170 anos, Jesus ainda não voltou. Depois de analisar os eventos de maneira detalhada, George Knight leva o leitor a refletir em algumas perguntas importantes: O que dizer da certeza do advento? O que pensar do compromisso absoluto com a mensagem e da expectativa gloriosa dos primeiros adventistas? Como manter viva a chama desse movimento? Em que reside a relevância de sua mensagem e missão?</p>$sinopse$
 where book_code = 'LIV-006' and length(trim(regexp_replace(coalesce(description, ''), '<[^>]*>', '', 'g'))) = 0;

-- LIV-007 · Pássaros - Suas Características e Hábitos  [CPB, produto 5004 (Pássaros - Suas Características e Hábitos]
update public.stock_books set description = $sinopse$<p>Faixa Etária: 7 a 9 anos</p><p>Relançamento! Conheça os pássaros, suas características e hábitos, através deste livro ricamente ilustrado. Fatos curiosos de pássaros do Brasil e do Mundo.</p>$sinopse$
 where book_code = 'LIV-007' and length(trim(regexp_replace(coalesce(description, ''), '<[^>]*>', '', 'g'))) = 0;

-- LIV-008 · Além da Morte - Respostas Bíblicas a Perguntas Milenares  [CPB, produto 20831 (Além da Morte)]
update public.stock_books set description = $sinopse$<p>Respostas Bíblicas a Perguntas Milenares</p><p>A morte é uma realidade implacável da experiência humana. Inquietos com o paradoxo da vida limitada, gurus, xamãs, filósofos, cientistas e teólogos tentaram oferecer respostas.</p><p>Afinal, o que acontece além da morte?</p><p>O mundo tem sido invadido pelo misticismo. Filmes, documentários e livros propagam a atividade de espíritos e relatos de quase-morte. Antigas crenças religiosas reforçam o dualismo platônico. As pessoas estão confusas ou seguras demais sobre fundamentos duvidosos. Outras vivem com medo da morte e dos mortos. Há esperança? Onde encontrar conforto?</p><p>A boa notícia está na verdade revelada nas Escrituras. Neste livro, Alberto R. Timm apresenta a visão bíblica sobre a morte. De maneira profunda e convidativa, conduzirá você a uma compreensão mais ampla e didática desse tema. Você vai entender como surgiu a ideia do inferno e o que a Bíblia diz sobre isso. Também vai descobrir se há algo melhor do que os prazeres desta vida.</p><p>É um material para você ler, reler e compartilhar com quem valoriza e ama.</p>$sinopse$
 where book_code = 'LIV-008' and length(trim(regexp_replace(coalesce(description, ''), '<[^>]*>', '', 'g'))) = 0;

-- LIV-009 · O Amanhã Começa Hoje  [CPB, produto 5230 (O Amanhã Começa Hoje)]
update public.stock_books set description = $sinopse$<p>Incentiva a manutenção de uma visão positiva sobre si mesmo e rejeita fórmulas mágicas para o sucesso. Toda pessoa tem um tremendo potencial e cabe a ela explorá-lo da melhor forma possível. Afinal, o amanhã depende de como se vive hoje!</p>$sinopse$
 where book_code = 'LIV-009' and length(trim(regexp_replace(coalesce(description, ''), '<[^>]*>', '', 'g'))) = 0;

-- LIV-010 · Amores que Matam - O Drama da Violência contra a Mulher  [CPB, produto 8150 (Amores que Matam)]
update public.stock_books set description = $sinopse$<p>A violência contra a mulher é um problema que tem atingido praticamente todas as classes sociais. Não importa se ela aparece em sua forma física ou psicológica, os danos têm sido terríveis e podem se tornar irreversíveis se não forem tratados a tempo. Este livro surge num momento oportuno, pois aborda questões como a violência doméstica, os mitos sobre o agressor e a mulher agredida, qual o papel que a igreja deve assumir com respeito ao assunto, e muito mais.</p>$sinopse$
 where book_code = 'LIV-010' and length(trim(regexp_replace(coalesce(description, ''), '<[^>]*>', '', 'g'))) = 0;

-- LIV-011 · O Apocalipse de João  [CPB, produto 18006 (O Apocalipse de João)]
update public.stock_books set description = $sinopse$<p>Desvendando o último livro da Bíblia</p><p>Hoje, o livro de Apocalipse atrai mais atenção do que nunca, inspirando filmes, livros, pesquisas e artigos jornalísticos em todo o mundo. Ainda assim permanece para muitos como um livro obscuro e incompreensível. Alguns ainda exploram esse livro bíblico para propagar ideias absurdas sobre o futuro, empurrando o livro ainda mais para a obscuridade. Contudo, a própria palavra grega apocalipse, "revelação", tem algo a dizer. O livro não está fechado, mas acessível a todo aquele que sinceramente deseja compreendê-lo.</p><p>Pode ser uma aventura cativante descobrir o significado histórico e espiritual de feras monstruosas, seres celestiais, números misteriosos e outras figuras enigmáticas descritas pelo apóstolo João. Além disso, o livro nos oferece uma compreensão única a respeito de Deus e de Sua atuação para eliminar toda a maldade neste mundo.</p><p>Escrita por Ranko Stefanovic, esta obra visa tornar mais fácil e interessante a interpretação do Apocalipse. Nesta leitura, você encontrará uma exposição dos principais temas abordados no livro bíblico, como por exemplo: as mensagens às sete igrejas, os sete selos, a marca da besta e os 144 mil. Também aprenderá as chaves hermenêuticas para desvendar símbolos proféticos e, assim, preparar-se para as coisas que vão acontecer.</p>$sinopse$
 where book_code = 'LIV-011' and length(trim(regexp_replace(coalesce(description, ''), '<[^>]*>', '', 'g'))) = 0;

-- LIV-012 · Apocalipse Verso por Verso  [CPB, produto 8207 (Apocalipse Verso por Verso)]
update public.stock_books set description = $sinopse$<p>O Apocalipse tem fama de ser um livro misterioso. Mas, com as chaves certas, é possível decifrar seus símbolos e apreciar sua mensagem. Com a ajuda deste comentário, você ganhará uma nova visão sobre: As filhas da Babilônia mística, os 144 mil, os quatro cavaleiros misteriosos, o monstro que surge do abismo, o significado da Revolução Francesa, o papel dos Estados Unidos na profecia, o número 666 e muito mais.</p>$sinopse$
