update public.stock_books set description = $sinopse$<p>Natureza da Bíblia, batismo infantil, predestinação, veneração de Maria, imortalidade da alma, vida após a morte, inferno, santidade do domingo...</p><p>Um número cada vez maior de cristãos questiona a autenticidade de suas crenças. Eles anseiam descobrir se aquilo em que foram doutrinados se baseia em ensinos da Bíblia ou se não passa de tradição.</p><p>Este livro foi escrito com o desejo de ajudá-los a fazer distinção entre verdade bíblica e crença popular.</p>$sinopse$
 where book_code = 'LIV-022' and length(trim(regexp_replace(coalesce(description, ''), '<[^>]*>', '', 'g'))) = 0;

